package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct { // 01 LOAN-REC, 21 bytes
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsInterest decimal.Decimal = decimal.Zero // PIC 9(9)V99 len=11 = 0
var WsTotal decimal.Decimal = decimal.Zero // PIC 9(11)V99 len=13 = 0
var WsCount int64 = 0 // PIC 9(5) len=5 = 0
var WsPrinEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var loanRec LoanRec
var loanLines []string
var loanIdx int

func pow10Dec(n int) decimal.Decimal {
	return decimal.New(1, int32(n))
}

func parseImplied(s string, scale int32) decimal.Decimal {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return decimal.New(n, -scale)
}

func parseIntField(s string) int64 {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return n
}

func storeDecimal(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	scaled := v.Mul(pow10Dec(scale)).Truncate(0)
	mod := pow10Dec(intDigits + scale)
	var rem decimal.Decimal
	if scaled.IsNegative() {
		posRem := scaled.Abs().Mod(mod)
		rem = posRem.Neg()
		if rem.IsZero() {
			rem = decimal.Zero
		}
	} else {
		rem = scaled.Mod(mod)
	}
	return rem.Shift(-int32(scale))
}

func formatEdited(v decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	var intPic string
	var decScale int
	if dotIdx < 0 {
		intPic = pic
		decScale = 0
	} else {
		intPic = pic[:dotIdx]
		decPart := pic[dotIdx+1:]
		decScale = 0
		for i := 0; i < len(decPart); i++ {
			if decPart[i] == '9' || decPart[i] == 'Z' {
				decScale++
			}
		}
	}
	intPlaceCount := 0
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == 'Z' || intPic[i] == '9' {
			intPlaceCount++
		}
	}
	q := v.Truncate(int32(decScale))
	absQ := q.Abs()
	scaledDec := absQ.Mul(decimal.New(1, int32(decScale))).Truncate(0)
	scaledInt := scaledDec.IntPart()
	var powDec int64 = 1
	for i := 0; i < decScale; i++ {
		powDec *= 10
	}
	var powInt int64 = 1
	for i := 0; i < intPlaceCount; i++ {
		powInt *= 10
	}
	var intVal int64
	var decVal int64
	if decScale == 0 {
		intVal = scaledInt
		if powInt != 0 {
			intVal = intVal % powInt
		}
		decVal = 0
	} else {
		intVal = (scaledInt / powDec) % powInt
		decVal = scaledInt % powDec
	}
	intStr := fmt.Sprintf("%0*d", intPlaceCount, intVal)
	decStr := ""
	if decScale > 0 {
		decStr = fmt.Sprintf("%0*d", decScale, decVal)
	}
	firstSig := intPlaceCount - 1
	for i := 0; i < intPlaceCount; i++ {
		if intStr[i] != '0' {
			firstSig = i
			break
		}
	}
	res := make([]byte, len(pic))
	digitIdx := 0
	decIdx := 0
	for i := 0; i < len(pic); i++ {
		if dotIdx >= 0 && i == dotIdx {
			res[i] = '.'
			continue
		}
		if dotIdx < 0 || i < dotIdx {
			c := pic[i]
			if c == 'Z' {
				d := intStr[digitIdx]
				if digitIdx < firstSig {
					res[i] = ' '
				} else {
					res[i] = d
				}
				digitIdx++
			} else if c == '9' {
				res[i] = intStr[digitIdx]
				digitIdx++
			} else if c == ',' {
				if digitIdx <= firstSig {
					res[i] = ' '
				} else {
					res[i] = ','
				}
			} else {
				res[i] = c
			}
		} else {
			c := pic[i]
			if c == '9' || c == 'Z' {
				if decIdx < len(decStr) {
					res[i] = decStr[decIdx]
				} else {
					res[i] = '0'
				}
				decIdx++
			} else {
				res[i] = c
			}
		}
	}
	return string(res)
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	scanner := bufio.NewScanner(f)
	loanLines = nil
	loanIdx = 0
	for scanner.Scan() {
		loanLines = append(loanLines, scanner.Text())
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		f.Close()
		os.Exit(1)
	}
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	f.Close()
	SummaryPara()
}

func ReadPara() {
	if loanIdx >= len(loanLines) {
		WsEofFlag = "Y"
		return
	}
	line := loanLines[loanIdx]
	loanIdx++
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	} else if len(line) > 21 {
		line = line[:21]
	}
	loanRec.LrAcct = line[0:6]
	princStr := line[6:15]
	loanRec.LrPrincipal = parseImplied(princStr, 2)
	rateStr := line[15:19]
	loanRec.LrRate = parseImplied(rateStr, 2)
	yearsStr := line[19:21]
	loanRec.LrYears = parseIntField(yearsStr)
}

func ProcessPara() {
	tmp := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(decimal.NewFromInt(loanRec.LrYears)).Shift(-2)
	rounded := tmp.Round(2)
	WsInterest = storeDecimal(rounded, 9, 2)
	WsTotal = storeDecimal(WsTotal.Add(WsInterest), 11, 2)
	WsCount = (WsCount + 1) % 100000
	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s\n", loanRec.LrAcct, WsPrinEd, WsIntEd)
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsCount)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func main() {
	MainPara()
}
